WITH micro AS (SELECT * FROM UNNEST(['PA-1506187-94551B72659E427F961D2F62CEBA7392','PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','MS-5006606-4693892971CF47B4B2684C3A94950BEE','BA-2921401-9177991E4861442EACDDC06DB91','BA-2929057-C5D11EE026A64399A6EF36764E8739E9']) AS id_car),pl AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023),mut AS (SELECT DISTINCT id_referencia_bacen,cpf,cnpj FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao=2023),ids AS (SELECT DISTINCT COALESCE(NULLIF(cpf,''),NULLIF(cnpj,'')) documento,CASE WHEN cpf IS NOT NULL AND cpf!='' THEN 'CPF' ELSE 'CNPJ' END tipo_documento,pl.id_referencia_bacen FROM pl JOIN mut USING(id_referencia_bacen) WHERE pl.id_car_norm IN (SELECT REPLACE(id_car,'-','') FROM micro)),emb AS (SELECT cpf_cnpj_embargado,COUNT(*) embargos,MIN(data_embargo) primeiro_embargo,MAX(data_embargo) ultimo_embargo,ARRAY_AGG(DISTINCT id_embargo LIMIT 10) ids_embargos FROM `basedosdados.br_ibama_fiscalizacao.area_embargada` WHERE ano BETWEEN 1987 AND 2026 GROUP BY cpf_cnpj_embargado) SELECT i.documento,i.tipo_documento,i.id_referencia_bacen,COALESCE(e.embargos,0) embargos,e.primeiro_embargo,e.ultimo_embargo,e.ids_embargos FROM ids i LEFT JOIN emb e ON e.cpf_cnpj_embargado=i.documento WHERE i.documento IS NOT NULL ORDER BY i.documento,i.id_referencia_bacen